#!/usr/bin/env node
/* Regenerate docs/icon-placeholders.md from index.html.
 *
 * That file has always said "this file is generated" and there has never been a generator,
 * which is exactly how it drifted: by 2026-08-22 it still listed `clipboard` and `document`,
 * two icons deleted from the source, and every line number in it was hundreds out. An index
 * of what remains to be drawn is worth nothing if it lists things that no longer exist.
 *
 *   node scripts/gen-icon-index.mjs          # rewrite the file
 *   node scripts/gen-icon-index.mjs --check  # exit 1 if it is out of date (for CI)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC  = join(ROOT, 'index.html');
const OUT  = join(ROOT, 'docs', 'icon-placeholders.md');

const html  = readFileSync(SRC, 'utf8');
const lines = html.split('\n');

/* Two shapes: the literal markup, and the ico() helper that builds it in JS. The helper's own
   definition matches its own pattern, so it is skipped by name rather than by line number. */
const MARKUP = /data-icon="([a-z-]+)"/g;
const CALL   = /\bico\('([a-z-]+)'/g;

const byName = new Map();
lines.forEach((text, i) => {
  if (/^function ico\(/.test(text)) return;          // the generator of the markup, not a site
  const hits = new Set();
  for (const m of text.matchAll(MARKUP)) hits.add(m[1]);
  for (const m of text.matchAll(CALL))   hits.add(m[1]);
  if (!hits.size) return;

  // A short, human-recognisable hint: the nearest label, title or trimmed source.
  const label = (text.match(/title="([^"]{2,60})"/) || text.match(/aria-label="([^"]{2,60})"/) || [])[1]
    || text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 78);

  for (const name of hits) {
    if (!byName.has(name)) byName.set(name, []);
    byName.get(name).push({ line: i + 1, label });
  }
});

const names = [...byName.keys()].sort();
const sites = [...byName.values()].reduce((n, a) => n + a.length, 0);

const body = `# Icon placeholders

Every emoji was removed from the app on **2026-08-17**. Each one left a placeholder naming
the icon that belongs there, so nothing has to be rediscovered when the real icons exist.

\`\`\`html
<i class="ico" data-icon="camera" aria-hidden="true"></i>
\`\`\`

**${sites} sites across ${names.length} distinct icons** — ${names.length} drawings is the whole job.

**Find them three ways**

| | |
|---|---|
| In the source | \`grep -n 'data-icon' index.html\` — and \`grep -n "ico('" index.html\` for the ones built in JS |
| In the console | \`document.querySelectorAll('.ico')\` |
| On screen | add \`?icons\` to the URL, or use test mode's **Icon slots** toggle — every placeholder outlines itself in place |

**Two kinds.** Most render as *nothing*, so the app looks finished today. A few marked
\`ico-live\` sit where the emoji **was** the control — the favourite heart, the note marker —
and draw a small neutral box instead, because rendering nothing would remove the affordance.
Those also carry \`data-state="on|off"\`.

**To replace one:** swap the \`<i>\` for your SVG. \`ico(name, extra, state)\` in \`index.html\`
is the single place the markup is generated for the JS-built ones.

> **Do not edit this file by hand — regenerate it:**
> \`\`\`
> node scripts/gen-icon-index.mjs
> \`\`\`
> Generated ${new Date().toISOString().slice(0, 10)} against a ${lines.length}-line \`index.html\`.
> It drifted for months before there was a generator, still listing two icons that had been
> deleted from the source.

---

## By icon

${names.map(n => {
  const rows = byName.get(n).map(r => `- \`index.html:${r.line}\` — ${r.label}`).join('\n');
  return `### \`${n}\`\n\n${rows}`;
}).join('\n\n')}
`;

const current = (() => { try { return readFileSync(OUT, 'utf8'); } catch { return ''; } })();

if (process.argv.includes('--check')) {
  // Line numbers and the date move on every edit, so compare the part that carries meaning:
  // which icons exist, and how many sites each has.
  const shape = s => (s.match(/^### `[a-z-]+`$/gm) || []).join(',');
  if (shape(current) !== shape(body)) {
    console.error('docs/icon-placeholders.md is out of date — run: node scripts/gen-icon-index.mjs');
    process.exit(1);
  }
  console.log(`  ok  icon index lists the ${names.length} icons that are actually in the source`);
} else {
  writeFileSync(OUT, body);
  console.log(`Wrote docs/icon-placeholders.md — ${sites} sites, ${names.length} icons.`);
}
